import React, { useState, useEffect } from 'react';
import '../styles/comicbooksmodal.css';

const ComicBooksModal = ({ isOpen, onClose, comics, character }) => {
  const [isLoading, setIsLoading] = useState(true);

  // Simulate the loading of comics, replace with your actual comics loading logic
  useEffect(() => {
    const loadComics = async () => {
      try {
        // Simulate a fetch call with a timeout
        setTimeout(() => {
          setIsLoading(false);
        }, 2000); // 2 seconds loading time
      } catch (error) {
        console.error('Failed to load comics:', error);
        setIsLoading(false);
      }
    };

    if (isOpen) {
      setIsLoading(true); // Reset loading state when modal opens
      loadComics();
    }
  }, [isOpen]); // Depend on isOpen to re-run effect when modal opens

  if (!isOpen) return null;

  return (
    <div className="comic-books-modal-overlay" onClick={onClose}>
      <div className="comic-books-modal-content" onClick={e => e.stopPropagation()}>
        {isLoading ? (
          <p>Loading comics...</p> // Or any other loading indicator
        ) : comics.length > 0 ? (
          <ul className="comic-grid-container">
            {comics.map(comic => (
              <li key={comic.id}>
                <div>
                  <img src={`${comic.thumbnail.path}.${comic.thumbnail.extension}`} alt={comic.title} style={{ width: '100%', height: 'auto' }} />
                  <h4>{comic.title}</h4>
                  <p>{comic.issueNumber && `Issue #${comic.issueNumber}`}</p>
                  <p>{comic.description || "No description available."}</p>
                  <a href={comic.urls[0].url} target="_blank" rel="noopener noreferrer">More Info</a>
                </div>
              </li>
            ))}
          </ul>
        ) : (
          <p>No comics available for this character.</p>
        )}
        {!isLoading && <button onClick={onClose}>Close</button>} {/* Render Close button only when not loading */}
      </div>
    </div>
  );
};

export default ComicBooksModal;
